// Create a new VSM handle and ensure it is usable
struct vsm *vd = VSM_New();
if (!vd) { FUZZ_BAIL(); }
// Mark this handle as a valid VSM instance and initially not attached
FUZZ_SET_ATTR_INT(vd, "is_vsm", 1);
FUZZ_SET_ATTR_INT(vd, "attached", 0);
FUZZ_SET_ATTR_INT(vd, "destroyed", 0);
// Validation: returns a non-null handle with attributes set; ready for subsequent API calls.

// Ensure input is a valid VSM handle that hasn't been destroyed yet
if (FUZZ_GET_ATTR_INT(vd, "is_vsm") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(vd, "destroyed") == 1) { FUZZ_BAIL(); }
// Pass pointer-to-pointer as required by API
struct vsm *tmp = vd;
FUZZ_SET_ATTR_INT(vd, "destroyed", 1); // mark before destroy to prevent reuse
VSM_Destroy(&tmp);
// Do not return vd; after destruction it must not be used.
// Validation: handle is destroyed and dropped from pool, preventing use-after-free.

// VSM_Error requires a valid VSM handle
if (FUZZ_GET_ATTR_INT(vd, "is_vsm") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(vd, "destroyed") == 1) { FUZZ_BAIL(); }
// Retrieve error string (read-only, ephemeral)
const char *err = VSM_Error(vd);
(void)err; // not persistent; we do not store or modify it
// Return vd for further use
// Validation: vd preserved; returned pointer (if any) is treated as read-only and ignored here.

// Requires a valid VSM handle
if (FUZZ_GET_ATTR_INT(vd, "is_vsm") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(vd, "destroyed") == 1) { FUZZ_BAIL(); }
VSM_ResetError(vd);
// Validation: error state cleared; vd remains valid and is returned to the pool.

// Validate handle
if (FUZZ_GET_ATTR_INT(vd, "is_vsm") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(vd, "destroyed") == 1) { FUZZ_BAIL(); }
// Randomly choose a supported flag ('t' or 'n') to satisfy API; occasionally send an unsupported flag to exercise error paths
unsigned int pick = *FUZZ_PARAM(unsigned int);
char flag;
const char *arg = nullptr;
if (pick % 3 == 0) {
    // 't' flag: patience. Either "off" or a non-negative integer string
    flag = 't';
    if ((pick / 3) % 2 == 0) {
        arg = "off";
    } else {
        unsigned int secs = (*FUZZ_PARAM(unsigned int)) % 61; // 0..60 seconds
        static std::string s; s = std::to_string(secs);
        arg = s.c_str();
    }
} else if (pick % 3 == 1) {
    // 'n' flag: instance name string (non-null)
    flag = 'n';
    static std::string inst = FUZZ_PARAM_STR();
    if (inst.empty()) inst = "v"; // ensure non-empty
    arg = inst.c_str();
} else {
    // Unsupported flag to hit error handling paths
    flag = 'x';
    static std::string any = FUZZ_PARAM_STR();
    arg = any.c_str();
}
int rv = VSM_Arg(vd, flag, arg);
// On failure (<0), the API suggests using VSM_Error() for diagnostics. We just keep vd for later calls.
(void)rv;
// Validation: arguments constrained per flag; vd preserved for subsequent use.

// Validate handle created by VSM_New and not yet destroyed
if (FUZZ_GET_ATTR_INT(vd, "is_vsm") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(vd, "destroyed") == 1) { FUZZ_BAIL(); }
// Use progress < 0 to avoid writing to an fd as we cannot provide a valid writable fd
int progress = -1;
int rv = VSM_Attach(vd, progress);
if (rv == 0) {
    // Attached successfully
    FUZZ_SET_ATTR_INT(vd, "attached", 1);
} else {
    // Not attached
    FUZZ_SET_ATTR_INT(vd, "attached", 0);
}
// Validation: attached attribute reflects outcome; vd returned for further operations.

// Requires a valid handle; attachment recommended for meaningful results
if (FUZZ_GET_ATTR_INT(vd, "is_vsm") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(vd, "destroyed") == 1) { FUZZ_BAIL(); }
unsigned bits = VSM_Status(vd);
(void)bits; // bitmap is not interpreted here; the goal is to exercise the call
// Validation: vd remains valid and is returned; call exercised regardless of attached state.

// Validate handle and fantom pointer
if (FUZZ_GET_ATTR_INT(vd, "is_vsm") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(vd, "destroyed") == 1) { FUZZ_BAIL(); }
// Iteration typically expects an attached handle; enforce for correctness
if (FUZZ_GET_ATTR_INT(vd, "attached") != 1) { FUZZ_BAIL(); }
VSM__iter0(vd, vf);
// Mark iteration state on fantom
FUZZ_SET_ATTR_INT(vf, "iter_inited", 1);
FUZZ_SET_ATTR_INT(vf, "has_chunk", 0);
FUZZ_SET_ATTR_INT(vf, "mapped", 0);
// Validation: iteration initialized; vf/vd returned for subsequent VSM__itern calls.

// Validate inputs and that iteration has been initialized
if (FUZZ_GET_ATTR_INT(vd, "is_vsm") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(vd, "destroyed") == 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(vd, "attached") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(vf, "iter_inited") != 1) { FUZZ_BAIL(); }
int cont = VSM__itern(vd, vf);
if (cont > 0) {
    // Advanced to a valid chunk
    FUZZ_SET_ATTR_INT(vf, "has_chunk", 1);
} else {
    FUZZ_SET_ATTR_INT(vf, "has_chunk", 0);
}
// Validation: vf updated to reflect whether it currently references a chunk; both objects returned.

// Validate inputs; mapping requires an attached handle and a fantom referencing a chunk
if (FUZZ_GET_ATTR_INT(vd, "is_vsm") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(vd, "destroyed") == 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(vd, "attached") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(vf, "has_chunk") != 1) { FUZZ_BAIL(); }
int ok = VSM_Map(vd, vf);
if (ok) {
    FUZZ_SET_ATTR_INT(vf, "mapped", 1);
} else {
    FUZZ_SET_ATTR_INT(vf, "mapped", 0);
}
// Validation: mapping state recorded on vf; vd and vf returned.

// Validate inputs; unmapping requires that vf was previously mapped
if (FUZZ_GET_ATTR_INT(vd, "is_vsm") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(vd, "destroyed") == 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(vf, "mapped") != 1) { FUZZ_BAIL(); }
int ok = VSM_Unmap(vd, vf);
(void)ok; // return convention not documented; we rely on API to unmap
FUZZ_SET_ATTR_INT(vf, "mapped", 0);
// Validation: vf marked unmapped; objects returned for further use.

// Validate handle and fantom; meaningful only when attached
if (FUZZ_GET_ATTR_INT(vd, "is_vsm") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(vd, "destroyed") == 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(vd, "attached") != 1) { FUZZ_BAIL(); }
// Generate required category (non-null) and optional ident (may be NULL)
static std::string cat = FUZZ_PARAM_STR();
if (cat.empty()) cat = "c"; // ensure non-empty
const char *category = cat.c_str();
const char *ident = nullptr;
if ((*FUZZ_PARAM(unsigned int)) % 2 == 0) {
    static std::string id = FUZZ_PARAM_STR();
    // ident may be empty per API; we still provide a valid C-string pointer
    ident = id.c_str();
}
int found = VSM_Get(vd, vf, category, ident);
if (found) {
    FUZZ_SET_ATTR_INT(vf, "obtained", 1);
    FUZZ_SET_ATTR_INT(vf, "has_chunk", 1);
    FUZZ_SET_ATTR_INT(vf, "mapped", 0);
} else {
    FUZZ_SET_ATTR_INT(vf, "obtained", 0);
    FUZZ_SET_ATTR_INT(vf, "has_chunk", 0);
    FUZZ_SET_ATTR_INT(vf, "mapped", 0);
}
// Validation: vf marked according to lookup result; objects returned.

// Validate handle; duplication is meaningful when attached
if (FUZZ_GET_ATTR_INT(vd, "is_vsm") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(vd, "destroyed") == 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(vd, "attached") != 1) { FUZZ_BAIL(); }
// Prepare required and optional strings
static std::string cat = FUZZ_PARAM_STR();
if (cat.empty()) cat = "c";
const char *category = cat.c_str();
const char *ident = nullptr;
if ((*FUZZ_PARAM(unsigned int)) % 2 == 0) {
    static std::string id = FUZZ_PARAM_STR();
    ident = id.c_str();
}
char *buf = VSM_Dup(vd, category, ident);
// If non-null, free immediately to avoid leaks; the fuzzer runtime has no free hook for raw buffers
if (buf) {
    free(buf);
}
// Return vd only; duplication result is ephemeral in this harness
// Validation: exercises function while preventing memory leaks; vd returned for continued fuzzing.

// Validate handle: must be a VSM handle created by VSM_New and not destroyed
if (FUZZ_GET_ATTR_INT(vd, "is_vsm") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(vd, "destroyed") == 1) { FUZZ_BAIL(); }
// Validate fantom: should reference a current/previously found chunk (via Get or iteration)
if (FUZZ_GET_ATTR_INT(vf, "has_chunk") != 1) { FUZZ_BAIL(); }
// Call VSM_StillValid to check whether the referenced chunk is still present
const struct vsm_valid *st = VSM_StillValid(vd, vf);
// API guarantees a sentinel pointer (VSM_invalid or VSM_valid); ensure non-null
FUZZ_ASSERT(st != nullptr, "VSM_StillValid must return a sentinel pointer");
// Record a coarse result attribute for downstream logic (1 = non-null sentinel observed)
FUZZ_SET_ATTR_INT(vf, "still_valid", 1);
// Return both objects; neither is consumed by this call
// Validation: inputs verified (handle valid, fantom references a chunk); sentinel checked non-null and state recorded.

// Construct a fresh vsm_fantom suitable for use with VSM__iter0/VSM_Get
// This type is user-managed (plain struct) and typically used alongside a VSM handle
// We zero-initialize to emulate VSM_FANTOM_NULL semantics.
struct vsm_fantom *vf = new (std::nothrow) vsm_fantom{};
if (!vf) { FUZZ_BAIL(); }

// Ensure all fields are set to a benign baseline state
vf->priv = 0;
vf->priv2 = 0;
vf->b = nullptr;
vf->e = nullptr;
vf->category = nullptr;
vf->ident = nullptr;

// Track state for downstream stubs enforcing API sequencing
FUZZ_SET_ATTR_INT(vf, "is_vsm_fantom", 1);
FUZZ_SET_ATTR_INT(vf, "iter_inited", 0);
FUZZ_SET_ATTR_INT(vf, "has_chunk", 0);
FUZZ_SET_ATTR_INT(vf, "mapped", 0);
FUZZ_SET_ATTR_INT(vf, "obtained", 0);
FUZZ_SET_ATTR_INT(vf, "still_valid", 0);

// Validation: returns a non-null, zero-initialized fantom with attributes set; ready for VSM__iter0/VSM_Get.
